"""Procedural Wispera rig parts + rig.json (wind spirit: floating violet-black hooded wisp, glowing cyan-white veins, trailing wisp tail, long reaching arms). Original art generated by this
script (no legacy pixels used). Run: python3 tools/assets/rig-gen/wispera.py <out_rig_dir>  (needs Pillow + numpy)
Look matches the Fiara/Pax/Treenoc/Morblass/Rokcore rigs: cel-banded ramp, dark outline, light upper-left rim. High contrast on purpose: deep violet body with bright cyan veins
and a white rim so it reads on both the dark Fire floor and the bright Air floor.
"""
import json, os, sys, zlib
import numpy as np
from PIL import Image, ImageDraw, ImageFilter
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import palette

OUT = sys.argv[1]
os.makedirs(os.path.join(OUT, "parts"), exist_ok=True)
SS = 4
W = 80 * SS
AIR = palette.ELEMENT_RAMPS["air"]
SPIRIT = [(0.0, (14, 8, 32)), (0.3, (40, 24, 90)), (0.58, (76, 52, 156)), (0.82, (128, 100, 210)), (1.0, (196, 176, 244))]
VEIN = [(0.0, (60, 200, 240)), (0.5, (150, 240, 255)), (1.0, (255, 255, 255))]
OUTLINE = np.array((8, 4, 22), np.float32)
RIM = np.array((230, 250, 255), np.float32)
FACE = (6, 3, 16)
EYE = (120, 255, 255)

# geometry in the 80x80 rest frame, E view (y down)
G = {
 "tail": dict(pts=[(34,54),(46,54),(40,64),(30,70),(18,68),(8,74),(4,66),(14,58),(26,56)], joint=(38,55), z=1, parent="torso", bias=-0.1),  # trailing wisp
 "armB": dict(pts=[(48,34),(56,36),(66,42),(74,52),(70,58),(62,52),(54,46),(46,42)], joint=(49,37), z=2, parent="torso", bias=-0.18),
 "torso": dict(pts=[(32,58),(26,46),(29,34),(40,29),(51,34),(54,46),(48,58),(40,62)], joint=(40,46), z=5, parent=None, bias=0.0),
 "head": dict(pts=[(32,28),(31,16),(37,7),(46,5),(53,12),(54,24),(48,31),(38,31)], joint=(43,29), z=7, parent="torso", bias=0.08),
 "armF": dict(pts=[(30,36),(20,38),(10,46),(6,56),(12,60),(20,52),(28,48)], joint=(29,39), z=8, parent="torso", bias=0.1),
}

def view_tf(view, part):
    if view == "E":
        return dict(sx=1.0, dx=-3 if part == "head" else 0, dy=0)
    if view == "SE":
        d = dict(sx=0.93, dx=2, dy=1)
        if part == "head": d = dict(sx=1.06, dx=-8, dy=4, scale=1.06)
        if part == "armF": d = dict(sx=0.95, dx=-3, dy=1)
        if part == "armB": d = dict(sx=0.95, dx=3, dy=1)
        if part == "torso": d = dict(sx=0.96, dx=1, dy=2)
        return d
    d = dict(sx=0.93, dx=-1, dy=-1)  # NE: seen from behind
    if part == "head": d = dict(sx=0.92, dx=-6, dy=-2, scale=0.94)
    if part == "armF": d = dict(sx=0.95, dx=1, dy=-1)
    if part == "armB": d = dict(sx=0.95, dx=2, dy=-1)
    if part == "torso": d = dict(sx=1.0, dx=-2, dy=-1)
    return d

def apply(tf, p, c=(40, 40)):
    s = tf.get("scale", 1.0)
    return (c[0] + (p[0] - c[0]) * tf["sx"] * s + tf["dx"], c[1] + (p[1] - c[1]) * s + tf["dy"])

def noise(rs, scale, sx=1, sy=1):
    """Smooth noise, stretched sx/sy times (flow streaks)."""
    h = max(2, W // (scale * sy) + 2); w = max(2, W // (scale * sx) + 2)
    small = rs.rand(h, w)
    return np.asarray(Image.fromarray((small * 255).astype(np.uint8)).resize((W, W), Image.BICUBIC), np.float32) / 255.0

def render(name, view, pts, g, seed):
    m = Image.new("L", (W, W), 0)
    d = ImageDraw.Draw(m)
    d.polygon([(x * SS, y * SS) for x, y in pts], fill=255)
    m = m.filter(ImageFilter.GaussianBlur(SS * 0.35))
    ma = np.asarray(m, np.float32) / 255.0
    rs = np.random.RandomState(seed)
    coarse = noise(rs, 8); mid = noise(rs, 4); fine = noise(rs, 2)
    yy, xx = np.mgrid[0:W, 0:W].astype(np.float32) / W
    # spirit: smooth violet cel bands with bright cyan vein lines (noise iso-lines), lit from the upper left
    t = 0.6 - 0.4 * yy - 0.2 * xx + 0.2 * (mid - 0.5) + 0.08 * (fine - 0.5) + g["bias"] + 0.2
    vein = np.abs(coarse - 0.5) < 0.045
    t = np.clip(np.round(np.clip(t, 0, 1) * 5.0) / 5.0, 0, 1)
    rgb = palette.ramp(SPIRIT, t)
    lt = np.clip(np.round(np.clip(0.4 + 0.8 * (1.0 - np.abs(coarse - 0.5) / 0.045) * (0.5 + 0.5 * fine), 0, 1) * 3.0) / 3.0, 0, 1)
    rgb = np.where(vein[..., None], palette.ramp(VEIN, lt), rgb)
    inner = np.asarray(m.filter(ImageFilter.MinFilter(SS * 3 + 1)), np.float32) / 255.0
    edge = np.clip(np.subtract(ma, inner), 0, 1)
    shifted = np.roll(np.roll(ma, SS * 2, axis=0), SS * 2, axis=1)
    lit = np.clip(np.subtract(ma, shifted), 0, 1) * inner.clip(0, 1)
    lit = np.asarray(Image.fromarray((lit * 255).astype(np.uint8)).filter(ImageFilter.GaussianBlur(SS * 0.5)), np.float32) / 255.0
    rgb = rgb * (1 - 1.0 * edge[..., None]) + OUTLINE[None, None, :] * (1.0 * edge[..., None])
    rgb = rgb * (1 - 0.7 * lit[..., None]) + RIM[None, None, :] * (0.7 * lit[..., None])
    return Image.fromarray(np.dstack([np.clip(rgb, 0, 255), ma * 255.0]).astype(np.uint8), "RGBA")

def face(im, tf, view):
    d = ImageDraw.Draw(im)
    x0, y0 = apply(tf, (38, 13)); x1, y1 = apply(tf, (54, 25))
    d.ellipse([x0 * SS, y0 * SS, x1 * SS, y1 * SS], fill=FACE + (255,))  # hood opening
    for ex, ey in ((44, 19), (50, 19)):
        x, y = apply(tf, (ex, ey))
        d.ellipse([x * SS - 1.5 * SS, y * SS - 1.5 * SS, x * SS + 1.5 * SS, y * SS + 1.5 * SS], fill=EYE + (255,))

parts = []
for view in ("E", "SE", "NE"):
    tfs = {k: view_tf(view, k) for k in G}
    for k, g in G.items():
        pts = [apply(tfs[k], p) for p in g["pts"]]
        im = render(k, view, pts, g, zlib.crc32((k + view).encode()) % 9973 + 7)
        if k == "head" and view != "NE":
            face(im, tfs[k], view)
        small = im.resize((80, 80), Image.LANCZOS)
        a = np.asarray(small)
        ys, xs = np.nonzero(a[..., 3] > 8)
        x0, x1, y0, y1 = int(xs.min()), int(xs.max()) + 1, int(ys.min()), int(ys.max()) + 1
        crop = small.crop((x0, y0, x1, y1))
        fname = f"{k}.png" if view == "E" else f"{k}_{view.lower()}.png"
        crop.save(os.path.join(OUT, "parts", fname))
        parts.append(dict(view=view, id=k, png=fname, joint=apply(tfs[k], g["joint"]), off=(x0, y0), size=crop.size))

byv = {v: {e["id"]: e for e in parts if e["view"] == v} for v in ("E", "SE", "NE")}
def pv(e):
    return [int(round(e["joint"][0])) - e["off"][0], int(round(e["joint"][1])) - e["off"][1]]
def at(v, pid):
    g = G[pid]; e = byv[v][pid]
    jx, jy = int(round(e["joint"][0])), int(round(e["joint"][1]))
    if g["parent"] is None:
        return [jx, jy]
    pe = byv[v][g["parent"]]
    return [jx - int(round(pe["joint"][0])), jy - int(round(pe["joint"][1]))]

rig_parts = []
for pid in list(G):
    g = G[pid]
    p = {"id": pid}
    if g["parent"]: p["parent"] = g["parent"]
    p["png"] = byv["E"][pid]["png"]; p["pivot"] = pv(byv["E"][pid]); p["at"] = at("E", pid); p["z"] = g["z"]
    p["views"] = {v: {"png": byv[v][pid]["png"], "pivot": pv(byv[v][pid]), "at": at(v, pid)} for v in ("SE", "NE")}
    rig_parts.append(p)

def c(**kw): return kw
def c(**kw): return kw
actions = {
 "idle": dict(frames=4, curves={  # floating bob
    "torso": c(dy=[0, -1, -2, -1]),
    "tail": c(rot=[0, 4, 7, 3]),
    "head": c(rot=[0, -2, -3, -1]),
    "armF": c(rot=[0, 3, 5, 2]),
    "armB": c(rot=[0, -3, -5, -2]),
 }),
 "walk": dict(frames=4, curves={  # drift: tail streams behind, arms trail
    "tail": c(rot=[-8, 0, 8, 0]),
    "torso": c(rot=[2, 0, -2, 0], dy=[-1, 0, -1, 0]),
    "head": c(rot=[-2, 0, 2, 0]),
    "armF": c(rot=[10, 0, -12, 0]),
    "armB": c(rot=[-12, 0, 10, 0]),
 }),
 # sonar pulse: both arms sweep forward and up, head tips back
 "cast": dict(frames=4, curves={
    "tail": c(rot=[0, 6, 10, -4]),
    "torso": c(rot=[0, -3, -5, 3], dy=[0, -1, -3, 0]),
    "head": c(rot=[0, -5, -8, 3]),
    "armF": c(rot=[-6, -44, -74, 6]),
    "armB": c(rot=[-6, -40, -66, 6]),
 }),
}

json.dump(dict(dirs=["E", "SE", "NE"], parts=rig_parts, actions=actions), open(os.path.join(OUT, "rig.json"), "w"), indent=2)
open(os.path.join(OUT, "license.txt"), "w").write(
"""Rig parts for wispera: original art generated by tools/assets/rig-gen/wispera.py (WP-art-consistency-batches, 2026-11-12, Claude). No pixels
are copied; silhouette and colours chosen by eye after the legacy public/assets/img/map/wispera.png. Licence: same as the
repository's own original code and art (still to be decided in README.md; owner to confirm).
""")
print("ok")
